 -- Shared synthetic setup ends after the enrollment; everything below rolls back.
 original:=to_jsonb(e);old_version:=clock_timestamp()-interval '1 second';rel:=gen_random_uuid();
 perform public.registrar_evento_ficha_pdf(actor,e.id,rel,'FICHA_PDF_GENERADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));
 if (select count(*) from public.auditoria where entidad='ficha_pdf' and registro_id=e.id)<>1 then raise exception 'Missing PDF event';end if;
 if (select new_values - array['artefacto_id','generated_at','expires_at','source_version','template_version','source_fingerprint'] from public.auditoria where entidad='ficha_pdf' and registro_id=e.id)<>'{}'::jsonb then raise exception 'PDF metadata contains unexpected fields';end if;
 if (select (new_values->>'expires_at')::timestamptz-(new_values->>'generated_at')::timestamptz from public.auditoria where entidad='ficha_pdf' and registro_id=e.id)<>interval '24 hours' then raise exception 'Wrong retention';end if;
 perform public.registrar_evento_ficha_pdf(coordinator,e.id,rel,'FICHA_PDF_DESCARGA_INICIADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));
 if not exists(select 1 from public.auditoria au where entidad='ficha_pdf' and registro_id=e.id and accion='FICHA_PDF_DESCARGA_INICIADA' and au.actor=coordinator) then raise exception 'Wrong download actor';end if;
 select count(*) into before_audit from public.auditoria;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,gen_random_uuid(),'FICHA_PDF_GENERADA','2000-01-01',old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Stale PDF accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,rel,'FICHA_PDF_GENERADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Duplicate event accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,rel,'ARBITRARY',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Arbitrary event accepted';exception when invalid_parameter_value then null;end;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,gen_random_uuid(),'FICHA_PDF_GENERADA',e.updated_at,clock_timestamp()-interval '25 hours',(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Expired generation accepted';exception when invalid_parameter_value then null;end;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,gen_random_uuid(),'FICHA_PDF_DESCARGA_INICIADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Missing artifact accepted';exception when no_data_found then null;end;
 update public.app_users set active=false where id=coordinator;
 begin perform public.registrar_evento_ficha_pdf(coordinator,e.id,rel,'FICHA_PDF_DESCARGA_INICIADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Inactive actor accepted';exception when insufficient_privilege then null;end;
 if (select count(*) from public.auditoria)<>before_audit then raise exception 'Denied PDF audited as success';end if;
 if (select to_jsonb(enrollment_row) from public.matricula enrollment_row where id=e.id)<>original then raise exception 'PDF changed enrollment';end if;
 if has_function_privilege('authenticated','public.registrar_evento_ficha_pdf(uuid,uuid,uuid,text,timestamptz,timestamptz,text)','EXECUTE') or has_function_privilege('anon','public.registrar_evento_ficha_pdf(uuid,uuid,uuid,text,timestamptz,timestamptz,text)','EXECUTE') then raise exception 'Client can forge PDF audit';end if;
 update public.matricula set estado_codigo='ANULADO',motivo_anulacion='H5 SYNTHETIC',anulado_por=actor,anulado_at=clock_timestamp() where id=e.id returning * into e;
 begin perform public.registrar_evento_ficha_pdf(actor,e.id,rel,'FICHA_PDF_DESCARGA_INICIADA',e.updated_at,old_version,(select source_fingerprint from public.matricula_ficha_fuente where id=e.id));raise exception 'Annulled download accepted';exception when sqlstate 'PT409' then null;end;
 set constraints all immediate;
end $$;
rollback;
